const crypto = require('crypto');
// Confirmed working header name: x-thikaa-signature
const SIGNATURE_HEADER = 'x-thikaa-signature';
// Instagram-only signing secret
const SIGNING_SECRET = 'ab41d1f152cf71f024498874e083d9c6b050c83fe8545aab';

const headers = $json.headers || {};
let receivedSignature =
  headers[SIGNATURE_HEADER] ||
  headers[SIGNATURE_HEADER.toLowerCase()] ||
  headers[SIGNATURE_HEADER.toUpperCase()] ||
  null;

// ثيكا بتحط بادئة 'sha256=' قبل الـ hash — لازم نشيلها قبل المقارنة
if (receivedSignature && receivedSignature.startsWith('sha256=')) {
  receivedSignature = receivedSignature.slice('sha256='.length);
}

let rawBodyBuffer;
try {
  rawBodyBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
} catch (e) {
  throw new Error('\u274c Raw body \u0645\u0634 \u0645\u062a\u0627\u062d \u2014 \u062a\u0623\u0643\u062f \u0625\u0646 Raw Body \u0645\u0641\u0639\u0651\u0644 \u0641\u064a \u0627\u0644\u0640 Webhook node (options.rawBody = true)');
}

const rawBodyString = rawBodyBuffer.toString('utf8');

const expectedSignature = crypto
  .createHmac('sha256', SIGNING_SECRET)
  .update(rawBodyString)
  .digest('hex');

let signatureValid = false;
if (receivedSignature) {
  try {
    const a = Buffer.from(String(receivedSignature));
    const b = Buffer.from(expectedSignature);
    signatureValid = a.length === b.length && crypto.timingSafeEqual(a, b);
  } catch (e) {
    signatureValid = false;
  }
}

let parsedBody = {};
try {
  parsedBody = JSON.parse(rawBodyString);
} catch (e) {
  parsedBody = {};
}

return [{
  json: {
    signature_valid: signatureValid,
    body: parsedBody,
    headers: $json.headers || {}
  }
}];

// نفس بنية payload ثيكا الموحدة:
// { event, instance_id, timestamp, data: { channel, conversation_id, message_id, from, from_user_id, text, attachments } }
const body = $json.body || {};

console.log('🔎 RAW THIKAA INSTAGRAM BODY:', JSON.stringify(body, null, 2));

if (body.event !== 'message.received') {
  return [{
    json: {
      is_status_update: true,
      event: body.event || null,
      raw_body: body
    }
  }];
}

const data = body.data || {};

const channelPatientId = data.from || null;
const messageText = data.text || null;
const messageType = data.attachments && data.attachments.length > 0 ? 'media' : 'text';
const channelCode = data.channel || 'ig';
const thikaaInstanceId = body.instance_id || null;
const messageId = data.message_id || null;

// مفتاح فريد لكل رسالة عشان نمنع المعالجة المكررة لو ثيكا عملت retry
const idempotencyKey = (thikaaInstanceId && messageId)
  ? `thikaa_ig_${thikaaInstanceId}_${messageId}`
  : null; // لو مفيش message_id، مفيش حماية idempotency لنفس الرسالة دي

if (!channelPatientId || !messageText) {
  return [{
    json: {
      is_status_update: true,
      raw_body: body
    }
  }];
}

return [{
  json: {
    is_status_update: false,
    channel_patient_id: String(channelPatientId).replace(/^\+/, ''),
    patient_name: data.from_user_name || null,
    message_text: messageText,
    message_type: messageType,
    channel_code: channelCode,
    thikaa_instance_id: thikaaInstanceId,
    message_id: messageId,
    idempotency_key: idempotencyKey,
    raw_body: body
  }
}];

const message = $('Parse Instagram Thikaa Message1').item.json;
const clinicLookup = $json;

return [{
  json: {
    ...message,
    clinic_id: clinicLookup.clinic_id || null,
    channel_id: clinicLookup.channel_id || null,
    thikaa_instance_id: clinicLookup.thikaa_instance_id || null
  }
}];

const original = $('Merge Clinic With Message Instagram Thikaa1').item.json;
const secretResult = $json;

return [{
  json: {
    ...original,
    thikaa_api_token: secretResult.api_token || null,
    thikaa_signing_secret: secretResult.signing_secret || null,
    thikaa_tenant_identifier: secretResult.tenant_identifier || null
  }
}];

