const original = $('Merge Clinic With Message Instagram Thikaa1').item.json;
const patientResult = $json;

let patientId = null;
if (patientResult.data && patientResult.data.length > 0) {
    patientId = patientResult.data[0].patient_id;
} else if (patientResult.patient_id) {
    patientId = patientResult.patient_id;
} else if (patientResult[0] && patientResult[0].patient_id) {
    patientId = patientResult[0].patient_id;
}

if (!patientId) {
    console.error('❌ No patient_id found:', JSON.stringify(patientResult));
    throw new Error('Failed to get patient_id from RPC response');
}

return [{
  json: {
    ...original,
    patient_id: patientId
  }
}];

const original = $('Merge Patient Data Instagram Thikaa1').item.json;
const convResult = $input.item.json;

let conversationId = null;
let channelId = null;

if (convResult.conversation_id) {
    conversationId = convResult.conversation_id;
    channelId = convResult.channel_id || null;
} else if (convResult.result && convResult.result.conversation_id) {
    conversationId = convResult.result.conversation_id;
    channelId = convResult.result.channel_id || null;
} else if (Array.isArray(convResult) && convResult.length > 0) {
    conversationId = convResult[0].conversation_id || convResult[0].result?.conversation_id || null;
    channelId = convResult[0].channel_id || convResult[0].result?.channel_id || null;
} else if (convResult.data && Array.isArray(convResult.data) && convResult.data.length > 0) {
    conversationId = convResult.data[0].conversation_id || convResult.data[0].result?.conversation_id || null;
    channelId = convResult.data[0].channel_id || convResult.data[0].result?.channel_id || null;
}

if (!conversationId) {
    console.error('❌ No conversation_id found:', JSON.stringify(convResult, null, 2));
    throw new Error('❌ Failed to get conversation_id from RPC response');
}

if (!channelId) {
    channelId = original.channel_id || null;
}

return [{
    json: {
        ...original,
        conversation_id: conversationId,
        channel_id: channelId
    }
}];

const data = $input.item.json;

let replyText = data.reply_text ||
                data.response ||
                data.message ||
                data.answer ||
                data.body ||
                data.output ||
                data.result ||
                null;

if (!replyText || replyText.trim() === '') {
    replyText = 'عذراً، حصلت مشكلة في معالجة طلبك. حاول مرة أخرى 🙏';
}

if (replyText.length > 4000) {
    replyText = replyText.substring(0, 4000) + '...';
}

let patientId = data.channel_patient_id || data.to || data.recipient || null;

if (!patientId) {
    try {
        patientId = $('Parse Instagram Thikaa Message1').item.json.channel_patient_id || null;
    } catch (e) { console.log('⚠️ Could not get from Parse {L} Thikaa Message1'); }
}

if (!patientId) {
    console.warn('⚠️ No patient id found');
}

return [{
    json: {
        ...data,
        thikaa_recipient: patientId,
        thikaa_message: replyText
    }
}];

const src = $('Merge Conversation Data Instagram Thikaa1').item.json || {};
const core_payload = {
  clinic_id: src.clinic_id || null,
  channel_type: 'instagram',
  channel_provider: 'thikaa',
  channel_id: src.channel_id || null,
  patient_id: src.patient_id || null,
  conversation_id: src.conversation_id || null,
  message_text: src.message_text || '',
  message_id: src.message_id || null,
  source_event_id: src.idempotency_key || src.message_id || null,
  metadata: {
    instagram_user_id: src.channel_patient_id || null,
    message_type: src.message_type || 'text',
    thikaa_instance_id: src.thikaa_instance_id || null
  }
};
return [{ json: { ...src, core_payload } }];

